import{_ as b,o as p,c as a,ae as e}from"./chunks/framework.BrEqZt6s.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"philosophy/중철 공자.md","filePath":"philosophy/중철 공자.md"}'),l={name:"philosophy/중철 공자.md"};function t(i,r,o,_,s,n){return p(),a("div",null,[...r[0]||(r[0]=[e('<h2 id="공자" tabindex="-1">공자 <a class="header-anchor" href="#공자" aria-label="Permalink to &quot;공자&quot;">​</a></h2><p>공자는 어떤 인물인가<br> 일화, 시대적 배경, 문제의식<br> 중심개념은 무엇인가<br> 인과 예<br> 이상적 인간형<br> 군자<br> 이상적 정치<br> 덕치</p><p>사람은 사람과 더불어 살아가야하는 존재,<br> 도가 사라졌기 때문에 새롭게 수립하기 위해 개혁<br> 춘추시대<br> 봉건적 질서 해체, 새로운 사회, 정치, 사상이 형성<br> 종법사회 붕괴, 엘리트 중심의 중앙집권적 관료제<br> 과학기술의 발달과 철기문명으로 전환되며, 생산량이 늘고 잉여 생산물이 늘어나게됨.<br> 국가들간의 교류가 늘어나고 도시의 발달로 인해 혈연 중심에서 개인, 능력 중심으로 변화 -&gt; 사적 이익 추구및 정복 전쟁 활성화<br> 종법시대<br> 종을 법으로 삼는 제도<br> 종은 맏아들<br> 나머지 아들은 소종<br> 대종이 소종에게 땅을 분할, 소종은 다시 종과 소종으로 나뉨<br> 혈연 중심의 귀족제이며 가족적 유대감으로 묶인 관계<br> 주공이 이를 통해 주나라의 봉건적 질서를 마련, 이것이 주례</p><p>문제의식<br> 전쟁으로 인해 백성이 고통 받음.<br> 전쟁은 도가 사라졌기 때문이다. (천하무도)<br> 도를 세워야 함<br> 종법질서의 회복, 덕치정치, 현신(현명한 신하)등용<br> 선비를 군자다운 존재로 만들어야 한다<br> 인재를 선천적 혈연기반이 아닌 후천적 노력을 통해 인격, 학문적으로 성숙된 존재로 보았음 (주체적, 자율적 인간관 및 배움의 강조)</p><p>시간이 지남에 따라 촌수가 멀어지며 덕, 예라는 도덕적 권위만으로 제후를 통제하기 어려워짐.<br> 생산성의 증대로 인해 경제적 자립이 가능해지며 위계에 복종할 이유가 약해짐</p><p>공자:</p><ol><li>공동체 구성원을 착한 존재로 만들자.</li><li>덕치정치를 강화하자</li><li>사를 군자로 만들어 질서를 자율적으로 회복<br> (객관적, 강제적 규칙을 통해 구성원의 행위를 변화시키자는 법치도 나타나게됨)</li></ol><p>법치 반대<br> 백성을 형벌로 다스리면 백성은 형벌을 피하는데에만 신경을 쓰게되어 정작 중요한 부끄러움을 모르게 된다. 따라서 백성을 덕과 예를 통해 다스린다면 스스로 바로잡게 될 것이다.</p><h3 id="예와-법" tabindex="-1">예와 법 <a class="header-anchor" href="#예와-법" aria-label="Permalink to &quot;예와 법&quot;">​</a></h3><p>공통점 : 규범라는 점에서 비슷한 속성을 띔<br> 질서유지: 공동체 내의 갈드을 방지하고 공유된 사회적 관계를 형성한다<br> 행위의 기준: 무엇이 옳고 그른지에 대한 판단 근거 제공<br> 공익성 표방: 개인의 욕망을 조절하여 공동체의 안녕 도모<br> 차이점:</p><ol><li><p>규제 대상:<br> 예는 내면의 양심을 대상으로 함, 즉 행위가 일어나기 전의 마음가짐이나 태도를 규제. 행위자체보다 그 행위에 담긴 공경의 마음을 주로 봄<br> 법은 외면의 행위를 통제, 마음 속으로 누군가를 미워한다고 해서 처벌하지 않음</p></li><li><p>동력:<br> 예는 양심의 부끄러운 감정에 기반함. 스스로 부끄러움을 느끼게하여 자발적 교정을 유도<br> 법은 이기적 공포의 감정에 기반. 법은 위반했을때 닥칠 손해에 대한 공포심을 동력으로 삼으며, 인간의 이기적 본성을 전제에 두고 이를 억제하는 데 주력함</p></li><li><p>제재의 방식:<br> 예는 무례한 사람이라는 사회적 낙인을 통하여 공동체로부터의 소외나 관계의 단절의 형식으로 제재를 가함<br> 법은 물리적 강제와 박탈이 주된 제재</p></li><li><p>유연성의 측면<br> 예는 때와 장소, 상대에 따라 유연하게 다르며 맥락에 따른 최적의 중용을 찾고자함<br> 법은 법앞에 만인이 평등하다는 원칙아래에 누가 집행하더라도 동일한 경과가 나오는 일관성을 원칙으로 함.</p></li></ol><p>예는 내면적 덕과 외면적 법 사이의 개념.<br> 예를 덕의 외연화로 보았으며, 내면의 선한 본성을 확충하는데 예를 이용<br> 순자는 예를 법의 예비 단계이자 근거로 보았으며, 외적인 예의 규범을 통해 본성을 교화 하고자 하였음</p><p>극기복례<br> 나를 이기고 예로 돌아감<br> 이를 통하여 인을 실현할 수 있음</p><p>인<br> 사람다움<br> 사람인에 두 이 : 두사람 간의 바람직한 관계를 맺는 것<br> 인간을 관계적 존재로 보았으며 이는 오륜에서 볼 수 있음</p><p>인의 두 축<br> 충과 서 수기치인<br> 나를 다스려 타인을 다스림<br> 충은 나에게 있어 최선을 다하는 삶<br> 서는 내 마음을 근거로 타인을 이해하는 삶</p><p>군자란?</p><p>학이시습지면 불역열호아<br> 배우기를 좋아하는 사람<br> 인부지이불온이면 불역 군자호아</p><p>인부지이불온이면 불역군자호아<br> 주체적 인간관</p><p>공익 우선시, 이익보다 옳음, 말보다 행동을 우선시</p><p>덕치 정치<br> 공동체의 리더가 몸소 도덕적 삶을 살아감으로 공동체 구성원들로 하여금 도덕적 삶을 살아갈 수 있도록 하는것.<br> 솔선수범의 정치가 공자의 덕치 정치</p>',20)])])}const d=b(l,[["render",t]]);export{c as __pageData,d as default};
